import {fitCalibration,estimate} from './colorimetry-model.js';
import {formatConductance} from './conductivity-model.js';
import {CELL} from './voltaic-model.js';
export function questions(s){
 if(s.mode==='conductivity'){const row=s.records.find(r=>r.value>0&&r.cellConstant>0),g=row?.value??2,k=row?.cellConstant??1.5;return[
  {prompt:'Why does sodium chloride solution conduct much better than a sucrose solution of similar concentration?',answers:['Dissolved salt supplies mobile ions; dissolved sucrose remains molecular.','Dissolved salt supplies mobile electrons; dissolved sucrose fixes its ions.','Dissolved salt supplies moving molecules; dissolved sucrose stops moving.'],hint:'Distinguish ions in solution from electrons in metallic wires.'},
  {prompt:`${row?'Use a recorded reading.':'Supplied example:'} Conductance G = ${formatConductance(g)} mS and cell constant K = ${k.toFixed(4)} cm⁻¹. Calculate conductivity κ = GK in mS cm⁻¹.`,fields:[{id:'value',label:'Conductivity (mS cm⁻¹)',answer:g*k,tolerance:Math.max(.00002,g*k*.003)}],hint:'Multiply the conductance by the cell constant. Keep mS throughout.'},
  {prompt:'In a supplied dilute-NaCl example, conductance is 1.20 mS. Transfer 10.0 mL of this solution and dilute it to 50.0 mL. Keeping temperature and probe geometry fixed, assume conductance is proportional to concentration. Calculate the new conductance.',fields:[{id:'value',label:'Diluted conductance (mS)',answer:.24,tolerance:.001}],hint:'Use G₂/G₁ = c₂/c₁ = V₁/V₂. This linear approximation is for the stated strong-electrolyte example.'}
 ];}
 if(s.mode==='colorimetry'){const row=s.unknownReadings.at(-1),fit=row?fitCalibration(s.records,row.filter):null,a=row?.absorbance??.420,m=fit?.slope??20,b=fit?.intercept??.020,answer=(a-b)/m;return[
  {prompt:'Why should the colorimeter be blanked with the solvent using the same filter and cuvette conditions?',answers:['To reference the solvent and optical background before measuring the solute.','To remove all solute from the cuvette before measuring its concentration.','To force every sample to have the same transmission before measurement.'],hint:'Blanking establishes an optical reference; it does not correct every preparation mistake.'},
  {prompt:`${fit?'Use your fitted calibration and recorded unknown.':'Supplied example:'} A = mc + b, with m = ${m.toPrecision(8)} dm³ mol⁻¹ and b = ${b.toPrecision(8)}. The sample absorbance is ${a.toFixed(3)}. Calculate c.`,fields:[{id:'value',label:'Concentration (mol dm⁻³)',answer,tolerance:Math.max(1e-7,Math.abs(answer)*.005)}],hint:'Rearrange to c = (A − b)/m. A numerical result does not establish that the calibration was valid.'},
  {prompt:'A supplied example gives 0.0120 mol dm⁻³ for a diluted sample. It was prepared by diluting 5.00 mL of the original sample to 25.00 mL. Calculate the original concentration.',fields:[{id:'value',label:'Original concentration (mol dm⁻³)',answer:.060,tolerance:.0001}],hint:'Multiply the diluted concentration by final volume / aliquot volume.'}
 ];}
 const row=s.records.filter(r=>r.loaded&&Math.abs(r.current)>0).at(-1),current=Math.abs(row?.current??6.0),seconds=60;return[
  {prompt:'During normal discharge of a zinc–copper voltaic cell, which statement describes the charge flow?',answers:['Electrons flow Zn → Cu in the wire; ions move through the salt bridge.','Electrons flow Cu → Zn in the wire; ions move through the salt bridge.','Electrons flow Zn → Cu through the bridge; ions move through the wire.'],hint:'Zinc is oxidised at the anode; copper ions are reduced at the cathode. The bridge carries ions.'},
  {prompt:`${row?'Use a recorded current magnitude.':'Supplied example:'} Assume I = ${current.toFixed(3)} mA stays constant for ${seconds} s. Use Q = It and n(Cu) = Q/(2F), where F = 96 485 C mol⁻¹. Calculate copper deposited in mg using M(Cu) = 63.546 g mol⁻¹. This is a supplied constant-current calculation, not a claim that your current stayed constant.`,fields:[{id:'value',label:'Copper deposited (mg)',answer:current/1000*seconds/(2*CELL.F)*CELL.copperMass*1000,tolerance:.001}],hint:'Convert mA to A, calculate charge and moles, then convert copper mass from grams to milligrams.'},
  {prompt:'AHL extension: given E°(Cu²⁺/Cu) = +0.34 V and E°(Zn²⁺/Zn) = −0.76 V, calculate E°cell for zinc oxidation and copper-ion reduction. These are standard-state data, not a loaded meter reading.',fields:[{id:'value',label:'Standard cell potential (V)',answer:1.10,tolerance:.005}],hint:'Use E°cathode − E°anode. Subtract the negative zinc reduction potential.'}
 ];
}
export function reviewSummary(s){
 if(s.mode==='conductivity')return `<p>${s.records.length?'Your recorded values remain below.':'No valid readings were recorded; the numerical review uses a labelled example.'} A near-zero reading with good contact differs from a disconnected circuit. Sugar remains molecular; ionic solids need mobile charge carriers. Weak-acid ionisation, dilution and carried liquid films can change the result.</p><p>Teaching model: fixed 25 °C, approximate limiting ionic conductivities, ideal dilute solutions, no electrode polarisation or temperature drift. Probe geometry affects conductance; it is not conductivity by itself.</p>`;
 if(s.mode==='colorimetry'){const e=estimate(s);return `<p>${e?`Calibration estimate: ${e.value.toPrecision(5)} mol dm⁻³. ${e.extrapolated?'This lies outside your calibration interval; it is extrapolation.':'This lies inside your calibration interval.'}`:'Record at least three distinct standard concentrations and an unknown at the same filter to obtain a calibration estimate.'} A straight line does not prove correct sample preparation or correct labels.</p><p>Check blank/filter consistency, solvent, cuvette orientation, fingerprints, fill height, lid and preparation volumes. Optical coefficients and stray light are teaching defaults, not a sourced CuSO₄ spectrum. Calibration is fitted from your entered concentrations and observed absorbances; it does not use the hidden unknown concentration.</p>`;}
 return `<p>Zn(s) → Zn²⁺(aq) + 2e⁻; Cu²⁺(aq) + 2e⁻ → Cu(s). Zinc loses metal; copper gains it. During normal discharge, zinc is the negative anode and copper is the positive cathode. Reversing meter leads changes the sign of the reading, not these chemical roles. K⁺ moves toward the copper half-cell and NO₃⁻ toward the zinc half-cell in the ideal KNO₃ bridge model. A voltage indication without a bridge is not evidence of sustained discharge.</p><p>Teaching model: fixed 25 °C, ideal activities, rounded E° = 1.10 V, 100 Ω load and 70 Ω internal resistance. Concentration correction is included for the model, not presented as required common-content Nernst work. Standard-potential calculation is explicitly AHL. Junction potentials, kinetics/passivation, gas reactions and transient bridge charging are omitted. Copper can also deposit directly on zinc placed in Cu²⁺ solution.</p>`;
}
export function calibrationGraph(s){const rows=s.records,filter=s.filter,points=rows.filter(r=>r.filter===filter),fit=fitCalibration(rows,filter),maxX=Math.max(.05,...points.map(r=>r.concentration))*1.1,minY=Math.min(0,...points.map(r=>r.absorbance))-.05,maxY=Math.max(1,...points.map(r=>r.absorbance))*1.1,plot=(c,a)=>`${60+570*c/maxX},${245-220*(a-minY)/(maxY-minY)}`;
 return `<svg class="calibration-graph" viewBox="0 0 660 300" role="img" aria-label="Measured absorbance against entered standard concentration"><rect x="60" y="25" width="570" height="220" fill="#faf9ee"/>${Array.from({length:6},(_,i)=>`<path d="M60 ${245-i*44}H630M${60+i*114} 25V245" stroke="#d2ded4"/><text x="52" y="${249-i*44}" text-anchor="end" font-size="10">${(minY+(maxY-minY)*i/5).toFixed(2)}</text><text x="${60+i*114}" y="262" text-anchor="middle" font-size="10">${(maxX*i/5).toFixed(3)}</text>`).join('')}<path d="M60 25V245H630" stroke="#38576b" fill="none"/>${fit?`<polyline points="${plot(0,fit.intercept)} ${plot(maxX,fit.slope*maxX+fit.intercept)}" stroke="#42857b" stroke-width="2" fill="none"/>`:''}${points.map(r=>`<circle cx="${60+570*r.concentration/maxX}" cy="${245-220*(r.absorbance-minY)/(maxY-minY)}" r="4" fill="#315f90"/>`).join('')}<text x="345" y="292" text-anchor="middle" font-size="12">Entered concentration / mol dm⁻³</text><text transform="translate(17 140) rotate(-90)" text-anchor="middle" font-size="12">Absorbance</text></svg>${fit?`<p>A = ${fit.slope.toPrecision(5)}c ${fit.intercept<0?'−':'+'} ${Math.abs(fit.intercept).toPrecision(4)} · R² = ${fit.r2.toFixed(4)} · ${fit.n} standards (${filter} filter)</p>`:'<p>Record three distinct standard concentrations at this filter to fit a line.</p>'}`;
}
